void USART1_IRQHandler(void) {
    if (!(USART1->SR & USART_SR_TXE)) return;
    if (tx_tail == tx_head) {
        USART1->CR1 &= ~USART_CR1_TXEIE;  // nothing to send
        return;
    }
    USART1->DR = tx_buf[tx_tail];
    tx_tail = (tx_tail + 1) % TX_LEN;
}

